Certainly! Below is a short Go program that demonstrates how to create an HTTP client that performs mutual TLS (mTLS) with self-signed certificates provided via an input file. This example assumes you have the client's certificate and key files available.

```go
package main

import (
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"io/ioutil"
	"net/http"
)

func main() {
	// Load the client's certificate and key
	certPEMBlock, err := ioutil.ReadFile("client-cert.pem")
	if err != nil {
		fmt.Printf("Failed to read client certificate: %v\n", err)
		return
	}

	keyPEMBlock, err := ioutil.ReadFile("client-key.pem")
	if err != nil {
		fmt.Printf("Failed to read client key: %v\n", err)
		return
	}

	// Load the CA certificate that signed the server's certificate
	caCertPool := x509.NewCertPool()
	caCertPEMBlock, err := ioutil.ReadFile("ca-cert.pem")
	if err != nil {
		fmt.Printf("Failed to read CA certificate: %v\n", err)
		return
	}
	caCertPool.AppendCertsFromPEM(caCertPEMBlock)

	// Create a TLS configuration with the client's certificate and key
	tlsConfig := &tls.Config{
		Certificates: []tls.Certificate{
			{
				Certificate: [][]byte{certPEMBlock},
				PrivateKey:  loadPrivateKey(keyPEMBlock),
			},
		},
		RootCAs: caCertPool,
	}

	// Create a transport with the TLS configuration
	transport := &http.Transport{
		TLSClientConfig: tlsConfig,
	}

	// Create an HTTP client with the transport
	client := &http.Client{
		Transport: transport,
	}

	// Make an HTTPS request
	resp, err := client.Get("https://example.com")
	if err != nil {
		fmt.Printf("Failed to make request: %v\n", err)
		return
	}
	defer resp.Body.Close()

	// Print the response status
	fmt.Printf("Response status: %s\n", resp.Status)
}

// loadPrivateKey loads a private key from a PEM-encoded block.
func loadPrivateKey(keyPEMBlock []byte) interface{} {
	key, err := tls.X509KeyPair([]byte("client-cert.pem"), keyPEMBlock)
	if err != nil {
		fmt.Printf("Failed to load private key: %v\n", err)
		return nil
	}
	return key.PrivateKey
}
```

### Notes:
1. **Files**: Ensure you have `client-cert.pem`, `client-key.pem`, and `ca-cert.pem` files in the same directory as your Go program. These files should contain the client's certificate, client's private key, and the CA certificate that signed the server's certificate, respectively.
2. **loadPrivateKey Function**: The `loadPrivateKey` function is a placeholder and might need adjustments based on the format of your private key. The example assumes the key is in PEM format and directly uses `tls.X509KeyPair` to load the key.
3. **URL**: Replace `"https://example.com"` with the actual URL of the server you are trying to connect to.

This program sets up an HTTP client that performs mutual TLS authentication with the provided client certificate and key, and verifies the server's certificate against the provided CA certificate.
